package hamming
import "testing"
var _ func(string, string) int = Hamming
func TestSpec(t *testing.T) {
cases:=[]struct{a,b string;want int}{
{"","",0},
{"a","a",0},
{"a","b",1},
{"karolin","kathrin",3},
{"abc","abd",1},
{"abc","ab",-1},
{"","a",-1},
{"Go","go",1},
{"é","e",1},
{"é","è",1},
{"é","é",-1},
{"日本語","日本人",1},
{"🚀a","🚀b",1},
{"🚀","🛸",1},
{"a b","a\tb",1},
{"1011101","1001001",2},
{"GAGCCTACTAACGGGAT","CATCGTAATGACGGCCT",7},
{"aaaa","bbbb",4},
{"ab","ba",2},
{"AbC","aBc",3},
{"","",1000},
{"","",500},
{"ab","abc",-1},
{"été","ete",2},
{"\xff","\xfe",0},
{"a\xff","a\x80",0},
{"\xff","é",1},
{"\xffa","\xff",-1},
{"\xff\xff","ab",2},
}
for _,c:=range cases { if got:=Hamming(c.a,c.b);got!=c.want {t.Errorf("%q %q: got %d want %d",c.a,c.b,got,c.want)};if Hamming(c.b,c.a)!=c.want {t.Errorf("%q %q: not symmetric",c.b,c.a)};if Hamming(c.a,c.b)!=c.want {t.Fatal("nondeterministic")}}
}
